SELECT cs.canonical_smiles, cr_s.compound_name AS substrate_compound_name, cr_p.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records cr_s ON m.substrate_record_id = cr_s.record_id JOIN compound_structures cs ON cr_s.molregno = cs.molregno JOIN compound_records cr_p ON m.drug_record_id = cr_p.record_id WHERE m.enzyme_name = 'CYP2B6' ORDER BY cs.canonical_smiles ASC, cr_s.compound_name ASC, cr_p.compound_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
